mapper.select:
SELECT a.announcement_id, a.title, a.summary, a.content, a.published_at, a.is_pinned, a.target,
       CASE WHEN CAST(#{userId} AS BIGINT) IS NULL THEN NULL ELSE r.announcement_id IS NOT NULL END AS is_read
FROM announcements a
LEFT JOIN announcement_reads r ON r.announcement_id = a.announcement_id AND r.user_id = #{userId}
WHERE a.placement = #{placement} AND a.enabled = TRUE AND a.published_at <= #{now}
ORDER BY a.is_pinned DESC, a.published_at DESC, a.announcement_id DESC LIMIT #{limit}

SELECT COUNT(*) FROM announcements a
WHERE a.placement = #{placement} AND a.enabled = TRUE AND a.published_at <= #{now}
  AND NOT EXISTS (SELECT 1 FROM announcement_reads r WHERE r.announcement_id = a.announcement_id AND r.user_id = #{userId})
